// Prismatic Flutter Logo (Inspired by iOS Prismatic Flow aesthetic)
// A 3D sculptural Flutter logo crafted from iridescent transparent glass
// with thin-film interference, chromatic dispersion, and spotted highlights.

// ============================================================================
// --- CONFIGURATION CONSTANTS (Tweak these to customize shader behavior) -----
// ============================================================================

// --- Glass Transparency & Surface Look ---
#define GLASS_TRANSPARENCY      0.65    // 0.0 = solid opaque pearlescent, 1.0 = clear glass
#define FLUTTER_TINT_AMOUNT     0.40    // Blend amount of signature Flutter blue tint
#define FRESNEL_POWER           2.8     // View-angle reflection power (concentrates on edges)

// --- Highlight & Specular Settings ---
#define HIGHLIGHT_INTENSITY     3.5     // Brightness of specular highlight spots
#define HIGHLIGHT_SHARPNESS     80.0    // Specular tightness / glossiness (higher = smaller tighter spots)
#define HIGHLIGHT_SPOTTEDNESS   0.75    // 0.0 = uniform smooth streak, 1.0 = highly concentrated spots
#define HIGHLIGHT_DISPERSION    0.12    // Chromatic dispersion (prism color split) in highlights
#define RIM_GLINT_INTENSITY     4.0     // Razor highlight intensity along curved bevels

// --- Iridescence & Animation ---
#define IRID_FLOW_SPEED         0.25    // Speed of spectral waves flowing across the logo
#define IRID_SPECTRUM_FREQ      0.35    // Density/frequency of rainbow cycles
#define IRID_FRINGE_INTENSITY   0.15    // Thin-film interference fringe sharpness

// --- 3D Logo Dimensions & Motion ---
#define LOGO_SCALE              1.08    // Size of the Flutter logo in viewport
#define LOGO_THICKNESS          0.080   // Depth/thickness of the glass slabs
#define LOGO_ROUNDNESS          0.032   // Bevel roundness radius of edges
#define LOGO_FLOAT_SPEED        0.40    // Idle floating & tilting speed in 3D

// --- Background & Bloom ---
#define CORONA_BLOOM_GLOW       0.15    // Luminous chromatic glow around logo on OLED black
#define CORONA_FALLOFF          22.0    // Falloff rate of the background corona
// ============================================================================

mat2 rot2D(float a) {
    float c = cos(a), s = sin(a);
    return mat2(c, -s, s, c);
}

float dot2(vec2 v) {
    return dot(v, v);
}

// Exact 2D distance to a convex quadrilateral
float sdQuad(vec2 p, vec2 v0, vec2 v1, vec2 v2, vec2 v3) {
    vec2 e0 = v1 - v0; vec2 w0 = p - v0;
    vec2 e1 = v2 - v1; vec2 w1 = p - v1;
    vec2 e2 = v3 - v2; vec2 w2 = p - v2;
    vec2 e3 = v0 - v3; vec2 w3 = p - v3;

    vec2 b0 = w0 - e0 * clamp(dot(w0, e0) / dot(e0, e0), 0.0, 1.0);
    vec2 b1 = w1 - e1 * clamp(dot(w1, e1) / dot(e1, e1), 0.0, 1.0);
    vec2 b2 = w2 - e2 * clamp(dot(w2, e2) / dot(e2, e2), 0.0, 1.0);
    vec2 b3 = w3 - e3 * clamp(dot(w3, e3) / dot(e3, e3), 0.0, 1.0);

    float d = min(min(dot2(b0), dot2(b1)), min(dot2(b2), dot2(b3)));

    float s = 1.0;
    bvec3 c0 = bvec3(p.y >= v0.y, p.y < v1.y, e0.x * w0.y > e0.y * w0.x);
    if ((c0.x && c0.y && c0.z) || (!c0.x && !c0.y && !c0.z)) s = -s;
    bvec3 c1 = bvec3(p.y >= v1.y, p.y < v2.y, e1.x * w1.y > e1.y * w1.x);
    if ((c1.x && c1.y && c1.z) || (!c1.x && !c1.y && !c1.z)) s = -s;
    bvec3 c2 = bvec3(p.y >= v2.y, p.y < v3.y, e2.x * w2.y > e2.y * w2.x);
    if ((c2.x && c2.y && c2.z) || (!c2.x && !c2.y && !c2.z)) s = -s;
    bvec3 c3 = bvec3(p.y >= v3.y, p.y < v0.y, e3.x * w3.y > e3.y * w3.x);
    if ((c3.x && c3.y && c3.z) || (!c3.x && !c3.y && !c3.z)) s = -s;

    return s * sqrt(d);
}

// 3D extrusion of 2D SDF with smooth rounded bevel
float opExtrudeRound(float d2d, float z, float halfThick, float roundness) {
    vec2 w = vec2(d2d, abs(z) - (halfThick - roundness));
    return min(max(w.x, w.y), 0.0) + length(max(w, 0.0)) - roundness;
}

// Flutter logo 3D SDF
vec3 mapFlutter(vec3 p, float time) {
    // Idle floating and gentle 3D tilt
    float pitch = sin(time * LOGO_FLOAT_SPEED * 0.9) * 0.12 - 0.14;
    float yaw = cos(time * LOGO_FLOAT_SPEED * 0.8) * 0.16 + 0.24;
    float roll = sin(time * LOGO_FLOAT_SPEED * 0.7) * 0.04 + 0.05;

    p.yz = rot2D(pitch) * p.yz;
    p.xz = rot2D(yaw) * p.xz;
    p.xy = rot2D(roll) * p.xy;

    vec3 lp = p / LOGO_SCALE;

    // Official Flutter geometry vertices (normalized to center (0,0))
    // Piece 1: Top long wing
    vec2 p1_0 = vec2(0.222, 1.111);
    vec2 p1_1 = vec2(0.889, 1.111);
    vec2 p1_2 = vec2(-0.550, -0.328);
    vec2 p1_3 = vec2(-0.889, 0.000);

    // Piece 2: Middle chevron
    vec2 p2_0 = vec2(0.222, 0.086);
    vec2 p2_1 = vec2(0.889, 0.086);
    vec2 p2_2 = vec2(-0.042, -0.844);
    vec2 p2_3 = vec2(-0.381, -0.507);

    // Piece 3: Bottom fold
    vec2 p3_0 = vec2(-0.042, -0.844);
    vec2 p3_1 = vec2(0.296, -0.507);
    vec2 p3_2 = vec2(0.889, -1.111);
    vec2 p3_3 = vec2(0.211, -1.111);

    float d1_2d = sdQuad(lp.xy, p1_0, p1_1, p1_2, p1_3);
    float d2_2d = sdQuad(lp.xy, p2_0, p2_1, p2_2, p2_3);
    float d3_2d = sdQuad(lp.xy, p3_0, p3_1, p3_2, p3_3);

    // 3D depth layering of the pieces (middle folds forward, bottom folds back)
    float d1_3d = opExtrudeRound(d1_2d, lp.z + 0.02, LOGO_THICKNESS, LOGO_ROUNDNESS);
    float d2_3d = opExtrudeRound(d2_2d, lp.z - 0.03, LOGO_THICKNESS, LOGO_ROUNDNESS);
    float d3_3d = opExtrudeRound(d3_2d, lp.z + 0.03, LOGO_THICKNESS, LOGO_ROUNDNESS);

    float dist = min(d1_3d, min(d2_3d, d3_3d)) * LOGO_SCALE;
    return vec3(dist, lp.x, lp.y);
}

vec3 calcNormal(vec3 p, float time) {
    vec2 e = vec2(0.0015, 0.0);
    float d = mapFlutter(p, time).x;
    return normalize(vec3(
        mapFlutter(p + e.xyy, time).x - d,
        mapFlutter(p + e.yxy, time).x - d,
        mapFlutter(p + e.yyx, time).x - d
    ));
}

// Thin-film iridescent cosine palette
vec3 spectralPalette(float phase) {
    // 6.2831853 = 2 * PI
    vec3 col = 0.5 + 0.5 * cos(6.2831853 * (phase + vec3(0.00, 0.33, 0.67)));

    // High frequency thin-film optical interference fringes
    float fringe = sin(6.2831853 * phase * 2.5) * IRID_FRINGE_INTENSITY;
    col.r = clamp(col.r + fringe, 0.0, 1.0);
    col.g = clamp(col.g + fringe * 0.3, 0.0, 1.0);
    col.b = clamp(col.b - fringe * 0.5, 0.0, 1.0);
    return col;
}

// ACES filmic tone mapping curve
vec3 acesFilm(vec3 x) {
    float a = 2.51;
    float b = 0.03;
    float c = 2.43;
    float d = 0.59;
    float e = 0.14;
    return clamp((x * (a * x + b)) / (x * (c * x + d) + e), 0.0, 1.0);
}

void mainImage(out vec4 fragColor, in vec2 fragCoord) {
    vec2 uv = (2.0 * fragCoord - iResolution.xy) / min(iResolution.x, iResolution.y);

    // Interactive mouse rotation
    vec2 m = iMouse.xy / iResolution.xy;
    float mouseYaw = (iMouse.z > 0.0) ? (m.x - 0.5) * 2.8 : 0.0;
    float mousePitch = (iMouse.z > 0.0) ? (m.y - 0.5) * 2.2 : 0.0;

    vec3 ro = vec3(0.0, 0.0, 3.2);
    vec3 rd = normalize(vec3(uv, -2.3));

    ro.xz = rot2D(mouseYaw) * ro.xz;
    rd.xz = rot2D(mouseYaw) * rd.xz;
    ro.yz = rot2D(mousePitch) * ro.yz;
    rd.yz = rot2D(mousePitch) * rd.yz;

    // Studio light setup: Front Key Light, Top-Right Rim Light, Top-Left Rim Light
    vec3 lightPos1 = vec3(0.5, 0.8, 2.2);    // Front Key Light -> bright specular hotspot on glass face!
    vec3 lightPos2 = vec3(1.8, 1.8, 0.5);    // Upper-right rim light
    vec3 lightPos3 = vec3(-1.5, 1.4, -0.4);  // Upper-left rim light

    // Raymarch
    float t = 0.8;
    float minD = 10.0;
    vec3 hitData = vec3(0.0);
    bool hit = false;

    for (int i = 0; i < 90; i++) {
        vec3 p = ro + t * rd;
        vec3 res = mapFlutter(p, iTime);
        if (res.x < minD) minD = res.x;
        if (res.x < 0.0012) {
            hit = true;
            hitData = res;
            break;
        }
        t += res.x * 0.82;
        if (t > 6.2) break;
    }

    vec3 col = vec3(0.0);

    if (hit) {
        vec3 pos = ro + t * rd;
        vec3 n = calcNormal(pos, iTime);

        float ndotv = max(dot(n, -rd), 0.0);
        float fresnel = 1.0 - ndotv;
        float fresnelPow = pow(fresnel, FRESNEL_POWER);

        // Spectral wave flowing diagonally across the Flutter wings
        float flow = -iTime * IRID_FLOW_SPEED;
        float phase = (hitData.y + hitData.z) * IRID_SPECTRUM_FREQ + fresnel * 0.65 + flow + 0.35;
        vec3 irid = spectralPalette(phase);

        // Front Key Light (produces localized circular specular hotspot on glass face)
        vec3 l1 = normalize(lightPos1 - pos);
        float diff1 = max(dot(n, l1), 0.0);

        // Rim Lights (produce razor highlights on beveled edges)
        vec3 l2 = normalize(lightPos2 - pos);
        vec3 l3 = normalize(lightPos3 - pos);

        vec3 ref = reflect(rd, n);
        float refl1 = max(dot(ref, l1), 0.0);
        float refl2 = max(dot(ref, l2), 0.0);
        float refl3 = max(dot(ref, l3), 0.0);

        // Spottedness modulator along the glass wings
        float spotWave = sin((hitData.y - hitData.z) * 3.5 + flow * 0.5 + 1.2) * 0.5 + 0.5;
        float spotFactor = pow(spotWave, 2.5);
        float spotMod = (1.0 - HIGHLIGHT_SPOTTEDNESS) + HIGHLIGHT_SPOTTEDNESS * spotFactor * 1.6;

        // Chromatic dispersion exponents for R, G, B channels
        float expR = HIGHLIGHT_SHARPNESS * (1.0 - HIGHLIGHT_DISPERSION);
        float expG = HIGHLIGHT_SHARPNESS;
        float expB = HIGHLIGHT_SHARPNESS * (1.0 + HIGHLIGHT_DISPERSION);

        vec3 specSpot = vec3(
            pow(refl1, expR),
            pow(refl1, expG),
            pow(refl1, expB)
        ) * spotMod * HIGHLIGHT_INTENSITY;

        // Edge bevel rim highlights
        float specRim1 = pow(refl2, 70.0) * 1.8;
        float specRim2 = pow(refl3, 70.0) * 1.6;
        float edgeGlint = fresnelPow * RIM_GLINT_INTENSITY;

        // Glass Fresnel reflectance (Schlick approximation)
        float glassReflectance = 0.04 + 0.96 * fresnelPow;
        float glassTransmission = mix(1.0, glassReflectance, GLASS_TRANSPARENCY);

        // Flutter blue glass base tint blended with thin-film iridescence
        vec3 flutterTint = vec3(0.20, 0.65, 0.98);
        vec3 bodyColor = mix(irid, flutterTint, FLUTTER_TINT_AMOUNT) * (0.22 * diff1 + 0.10) * glassTransmission;

        // Rainbow edge rims
        vec3 edgeCol = vec3(
            edgeGlint * (0.8 + 0.4 * irid.r),
            edgeGlint * (0.9 + 0.3 * irid.g),
            edgeGlint * (1.0 + 0.2 * irid.b)
        );

        // Specular glints composite with chromatic dispersion
        vec3 totalRim = (specRim1 + specRim2) * vec3(0.85, 0.92, 1.0);
        vec3 specCol = specSpot + totalRim;

        col = bodyColor + edgeCol + specCol;

        // Depth distance fade into darkness
        float fade = clamp((5.4 - t) / 2.0, 0.0, 1.0);
        col *= fade;
    } else {
        // Soft iridescent & Flutter cyan corona in deep OLED black
        float glow = exp(-minD * CORONA_FALLOFF) * CORONA_BLOOM_GLOW;
        vec3 glowCol = spectralPalette(uv.x * 0.3 + uv.y * 0.2 - iTime * 0.2);
        vec3 flutterGlow = vec3(0.2, 0.7, 1.0);
        col = glow * mix(glowCol, flutterGlow, 0.4);
    }

    // Filmic tone mapping & gamma correction
    col = acesFilm(col);
    col = pow(col, vec3(1.0 / 2.2));

    fragColor = vec4(col, 1.0);
}
